from typing import List

def minFlips(grid: List[List[int]]) -> int:
    m = len(grid)
    n = len(grid[0])

    # Calculate cost to make all rows palindromic
    cost_rows = 0
    for i in range(m):
        row = grid[i]
        for j in range(n // 2):
            if row[j] != row[n - 1 - j]:
                cost_rows += 1

    # Calculate cost to make all columns palindromic
    cost_cols = 0
    for j in range(n):
        for i in range(m // 2):
            if grid[i][j] != grid[m - 1 - i][j]:
                cost_cols += 1

    return min(cost_rows, cost_cols)
