from typing import List

def minFlips(grid: List[List[int]]) -> int:
    m = len(grid)
    n = len(grid[0])

    # Calculate the cost to make all rows palindromic
    row_cost = 0
    for i in range(m):
        # Only need to check the first half of the row
        for j in range(n // 2):
            if grid[i][j] != grid[i][n - 1 - j]:
                row_cost += 1

    # Calculate the cost to make all columns palindromic
    col_cost = 0
    for j in range(n):
        # Only need to check the first half of the column
        for i in range(m // 2):
            if grid[i][j] != grid[m - 1 - i][j]:
                col_cost += 1

    return min(row_cost, col_cost)

