def beautifulSubstrings(s: str, k: int):
    vowels_set = set("aeiou")
    count = 0
    n = len(s)

    # Use O(n^2) approach as n <= 1000 is small enough.
    for i in range(n):
        vowels = 0
        consonants = 0
        for j in range(i, n):
            if s[j] in vowels_set:
                vowels += 1
            else:
                consonants += 1

            # Check the two conditions for a "beautiful" substring
            if vowels == consonants and (vowels * consonants) % k == 0:
                count += 1

    return count
